const NUBIA_ERA_DOSSIERS = [
  {id:"origins",era:"ancient",year:"c. 3800–1500 ق.م",title:"الأصول القديمة: A-Group وC-Group",region:"النوبة السفلى ووادي النيل الأوسط",tone:"sand",text:"قبل قيام الممالك المعروفة، صنعت جماعات وادي النيل الجنوبي اقتصاداً وطقوساً وشبكات تبادل خاصة بها.",summary:"لا تبدأ النوبة مع أول اسم ملكي؛ تبدأ مع مجتمعات القرى والجبانات والخرز والخزف التي صنعت تاريخاً أطول من السلالات.",monograph:["تشير ثقافة A-Group، التي يؤرخ لها تقريباً بين 3800 و3100 قبل الميلاد، إلى مجتمعات في النوبة السفلى امتلكت صناعة خزف مميزة وشبكات تبادل بعيدة ومقابر ذات تفاوت اجتماعي. لا تعني تسمية الثقافة وجود دولة مركزية بالمعنى اللاحق، لكنها تكشف مجتمعاً منظماً على ضفاف النيل وفي طرق الصحراء.","ظهرت مجموعات C في النوبة السفلى والوسطى منذ نحو 2400 قبل الميلاد واستمرت طبقات منها حتى القرن السادس عشر قبل الميلاد تقريباً. الخزف ذو الزخارف المحفورة، والقبور الدائرية، وممارسات الدفن ليست زخرفة منفصلة عن الحياة؛ إنها أدلة على هوية وقرابة وحركة ورعي وتبادل مع مصر ووسط أفريقيا.","تتداخل هذه التواريخ مع صعود كرمة، لذلك لا يصح تقديم A-Group وC-Group كسلالم بسيطة تنتهي عند مملكة واحدة. الأثر يثبت مواد ومواقع وأنماطاً، بينما أسماء الجماعات ولغاتهم السياسية تحتاج إلى حذر ومقارنة، لا إلى تحويل التصنيف الأثري إلى اسم قبيلة معاصرة."].join(" "),milestones:[{period:"نحو 3800–3100 ق.م",title:"A-Group / المجموعة الأولى",detail:"خزف ومقابر وشبكات تبادل في النوبة السفلى؛ مرحلة تسبق الدولة المصرية القديمة وتجاورها زمنياً."},{period:"نحو 3100–2400 ق.م",title:"الحدود ليست جداراً",detail:"تتبدل طرق التجارة والسلطة بعد توحيد مصر، مع استمرار مجتمعات جنوب الشلال الأول في إنتاجها وهويتها."},{period:"نحو 2400–1550 ق.م",title:"C-Group / المجموعة الثالثة",detail:"زخارف خزفية ومدافن وقرى تعطي مادة واسعة لقراءة القرابة والطقس والحركة."}],lineage:"لا تُحوّل التسميات الأثرية A-Group وC-Group إلى أنساب أو قبائل حديثة؛ صلة الأجيال تحتاج مصادر مجتمعية منفصلة.",geopolitics:"كان الشلال الأول حدّاً متحركاً للتجارة والبعثات العسكرية، لا نهاية لعالم جنوبي مستقل.",evidence:["خزف A-Group وC-Group","مدافن النوبة السفلى","خرز ومواد مستوردة","نقوش وخرائط الإنقاذ الأثري"],landmarks:["النوبة السفلى","مقابر المجموعة C","طرق الصحراء","الشلال الأول"],sources:[{label:"British Museum / Nubia",url:"https://www.britishmuseum.org/collection/galleries/africa"},{label:"UNESCO / Nubian Monuments",url:"https://whc.unesco.org/en/list/88/"}]},
  {id:"kerma",year:"c. 2500–1500 ق.م",title:"كرمة: المملكة التي بنت الجنوب",region:"الشلال الثالث إلى الرابع",tone:"ochre",summary:"مملكة كرمة ليست مقدمة هامشية لتاريخ آخر؛ إنها تجربة دولة وتجـارة وطقس وعمارة بنت مركزها في الجنوب.",monograph:["نشأت كرمة في بيئة جعلت من النهر وشبكات الصحراء معاً أساساً للقوة. تكشف المدينة والدفوفة الغربية والمقابر عن مجتمع منظم، وعن سلطة كانت تدير الزراعة والتبادل والحركة بين وادي النيل ووسط أفريقيا.","ازدهرت كرمة تقريباً بين 2500 و1500 قبل الميلاد، وتطورت علاقتها بمصر من التبادل إلى التنافس ثم إلى الاحتلال في أواخر المرحلة. لا تختصر اللقى الخزفية والدفوفة والتقاليد الجنائزية في قصة تجارة فقط؛ فهي تسجل هوية سياسية وثقافية صنعتها مجتمعات كوشية مبكرة.","تكشف مراسلات ونقوش الدولة المصرية في عصر الدولة الوسطى عن ضغط متبادل على الحدود الجنوبية، بينما تكشف المقابر والقصور عن عالم كرمة من الداخل. يظل كثير من التفاصيل مفتوحاً للبحث، خصوصاً أسماء الحكام والبنية اليومية للمجتمع."].join(" "),milestones:[{period:"نحو 2500 ق.م",title:"صعود المركز الحضري",detail:"تتبلور كرمة كعاصمة ومركز تبادل في النوبة العليا."},{period:"نحو 2055–1650 ق.م",title:"الدولة الوسطى والحدود الجنوبية",detail:"تتنافس مصر وكرمة على الممرات والموارد، وتظهر حصون وطرق ونظم تبادل على جانبي الشلال."},{period:"نحو 1650–1500 ق.م",title:"الاحتلال والتحول",detail:"تصل الدولة المصرية الحديثة إلى كرمة، ثم تعيد تشكيل الموقع السياسي من دون محو الإرث الجنوبي."}],lineage:"تُعرف مملكة كرمة من خلال المواقع واللقى والوثائق المقارنة، لا من شجرة ملوك مكتملة يمكن إسقاطها على عائلات اليوم.",geopolitics:"كانت كرمة قوة تفاوض ومنافسة على طريق الذهب والماشية والبخور، وليست منطقة تابعة بلا سياسة.",evidence:["الدفوفة الغربية","الجبانات الملكية","خزف كرمة الأسود والأحمر","حصون الدولة الوسطى"],landmarks:["الدفوفة الغربية","مقابر كرمة","شبكات التجارة الجنوبية"],sources:[{label:"UNESCO / Nubian Monuments",url:"https://whc.unesco.org/en/list/88/"}]},
  {id:"napata",year:"c. 900–270 ق.م",title:"نبتة والأسرة الخامسة والعشرون",region:"جبل البركل والشلال الرابع",tone:"ember",summary:"من نبتة صعد حكم كوشي إلى الأسرة الخامسة والعشرين، وربط الجبل المقدس بالملكية والطقس والشرعية.",monograph:["ارتبطت نبتة بجبل البركل، وبشبكة من المعابد والمقابر والطرق التي جعلت من المشهد الطبيعي جزءاً من لغة الحكم. في هذه المنطقة تبلورت شرعية ملكية كوشية تستند إلى الطقس والذاكرة والقدرة على إدارة الوادي.","في التسلسل الملكي المعروف تاريخياً، حكم بعنخي/بيا نحو 747–716 ق.م، ثم شبكا نحو 716–702 ق.م، وشبتكو نحو 702–690 ق.م، وترهاقا نحو 690–664 ق.م، وتنتاماني نحو 664–653 ق.م تقريباً. هذه التواريخ تقريبية بحسب اختلاف الجداول، لكنها تثبت انتقال مركز القوة الكوشي إلى مصر خلال الأسرة الخامسة والعشرين.","بعد ضغط آشور وتراجع الحكم شمالاً بقيت نبتة مرجعاً رمزياً للملكية. المعابد والمقابر في جبل البركل ونوري والكرو تشكل أرشيفاً بصرياً لعالم سياسي لم ينته بانسحاب الجيش من الشمال."].join(" "),milestones:[{period:"نحو 900–750 ق.م",title:"تثبيت نبتة مركزاً ملكياً",detail:"تتوسع المعابد والجبانات حول جبل البركل، وتظهر شرعية كوشية مستقلة في وادي النيل الأوسط."},{period:"747–653 ق.م",title:"الأسرة الخامسة والعشرون",detail:"يحكم ملوك كوش أجزاء واسعة من مصر؛ بيا، شبكا، شبتكو، ترهاقا وتنتاماني أسماء مركزية في السجل الملكي."},{period:"664–656 ق.م",title:"الانسحاب من مصر",detail:"تضغط آشور على مصر، وتستمر كوش جنوباً مع بقاء نبتة مركزاً دينياً وسياسياً."}],lineage:"تُقرأ سلسلة الأسرة الخامسة والعشرين من النقوش والجبانات والآثار الملكية، ولا تعني تلقائياً نسباً لأي عائلة معاصرة.",geopolitics:"غيّر الحكم الكوشي تصور المركز والهامش في وادي النيل؛ تحركت القوة جنوباً وشمالاً معاً.",evidence:["نقوش ملوك كوش","جبل البركل","الكرو ونوري","تماثيل الأسرة الخامسة والعشرين"],landmarks:["جبل البركل","الكرو","نوري","نقوش ملوك الأسرة الخامسة والعشرين"],sources:[{label:"UNESCO / Gebel Barkal",url:"https://whc.unesco.org/en/list/1073/"}]},
  {id:"meroe",year:"c. 300 ق.م–350 م",title:"مروي: الكتابة والحديد والمدينة",region:"البطانة ومجرى النيل الأوسط",tone:"gold",summary:"مروي ليست صفاً من الأهرام فقط؛ إنها مدينة وورش وشبكات مياه ولغة لم تكتمل قراءة نصوصها.",monograph:["انتقل مركز الثقل الكوشي تدريجياً إلى مروي، حيث ساعدت موارد البطانة وشبكات المياه والطرق على بناء مدينة طويلة العمر. ارتبطت مروي بإنتاج الحديد، لكن اختزالها في معدن واحد يحجب الزراعة والورش والإدارة والطقوس التي حافظت على المدينة.","تظهر اللغة المروية في نظامي كتابة، الهيروغليفية المروية والكتابة المروية المتصلة، منذ أواخر القرن الثالث قبل الميلاد تقريباً. فُكّت قيمة الأصوات الأساسية إلى حد كبير، لكن الترجمة الكاملة للنصوص ما زالت مجالاً للبحث. لا يسمح هذا النقص بالتخمين؛ بل يفرض تمييز القراءة المؤكدة من التفسير.","تسجل الأهرام والمعابد والمدينة الملكية ومواقع الإنتاج طبقات مختلفة من المجتمع. أسهمت مروي في شبكات البحر الأحمر ووادي النيل ووسط أفريقيا، ثم تراجعت في القرن الرابع الميلادي تقريباً وسط عوامل سياسية وبيئية واقتصادية متداخلة."].join(" "),milestones:[{period:"نحو 300 ق.م",title:"مركز ملكي جديد",detail:"ينتقل مركز الثقل من نبتة إلى مروي تدريجياً، مع استمرار قداسة نبتة."},{period:"القرن الثاني ق.م",title:"الكتابة المروية",detail:"تستعمل الكتابة المروية في النقوش الملكية والجنائزية والإدارية، مع بقاء الترجمة غير مكتملة."},{period:"القرنان الأول–الثالث م",title:"المدينة والورش",detail:"تتوسع العمارة والورش وشبكات الماء والتجارة، وتظهر أدوار ملكية ونسوية بارزة في السجل."},{period:"نحو 350 م",title:"نهاية المركز المروي",detail:"يتراجع النظام السياسي المروي؛ التاريخ النهائي والأسباب محل نقاش ولا يختزل في عامل واحد."}],lineage:"تثبت النقوش أسماء ملوك وملكات، لكنها لا تمنح شجرة نسب كاملة للمجتمع المروي أو صلة مباشرة بعائلات حديثة.",geopolitics:"كانت مروي قوة إقليمية بين وادي النيل والبحر الأحمر ووسط أفريقيا، لا مجرد موقع أثري منعزل.",evidence:["النصوص المروية","الأهرام الشمالية","المدينة الملكية","ورش ومواقع الإنتاج"],landmarks:["الأهرام الشمالية","المدينة الملكية","معبد آمون","الكتابة المروية"],sources:[{label:"UNESCO / Archaeological Sites of Meroe",url:"https://whc.unesco.org/en/list/1336/"}]},
  {id:"christian-network",era:"christian",year:"c. 543–1500 م",title:"نوباتيا ومقُرة وعلوة: الممالك المسيحية",region:"من أسوان إلى النيل الأزرق",tone:"azure",summary:"ثلاثة مراكز سياسية ودينية صنعت قروناً من العمارة والكتابة والدبلوماسية؛ لا تُختصر في مرحلة انتقال بين مصر والسودان.",monograph:["تذكر المصادر التقليدية وصول بعثات مسيحية إلى النوبة في القرن السادس الميلادي، مع تواريخ تقريبية مثل 543 م لنوباتيا و580 م لمقُرة وعلوة. هذه ليست لحظة واحدة ولا تحولاً موحداً؛ دخلت المسيحية في تفاوض مع سلطات محلية وطقوس ولغات ومصالح تجارية.","ظهرت نوباتيا في الشمال ثم ارتبطت بمقُرة، وعاشت دنقلا القديمة مركزاً سياسياً ودينياً طويلاً. أما علوة فامتدت جنوباً حول سوبا والنيل الأزرق، وتظل مادتها الأثرية أقل اكتمالاً من الشمال. فرس وقصر إبريم والكنائس والوثائق تكشف فناً وإدارة وتعليماً وحياة يومية.","كان البقط، المؤرخ عادة إلى 651–652 م، إطاراً للعلاقة بين مقُرة والقوى العربية، لا شهادة بأن الحدود كانت ساكنة. استمرت الممالك المسيحية قروناً، وامتزج التحول الديني بالزواج والتجارة والتعليم والسلطة قبل تراجع المراكز السياسية بين القرنين الرابع عشر والخامس عشر."].join(" "),milestones:[{period:"543 م تقريباً",title:"بعثة إلى نوباتيا",detail:"تربط الروايات البيزنطية التحول المسيحي في الشمال بعهد جستنيان، مع اختلاف تفاصيل التسلسل."},{period:"580 م تقريباً",title:"مقُرة وعلوة",detail:"تترسخ مؤسسات مسيحية في مراكز النيل الأوسط والجنوب، مع تفاوت محلي واسع."},{period:"651–652 م / نحو 31 هـ",title:"البقط",detail:"معاهدة طويلة الأثر تفتح التجارة والتفاوض والحركة بين مقُرة والقوى العربية في الشمال."},{period:"القرن الرابع عشر–الخامس عشر",title:"تحول المراكز",detail:"تتراجع الممالك المسيحية سياسياً على مراحل، فيما تستمر آثارها ولغاتها وطقوسها في الذاكرة."}],lineage:"الأساقفة والملوك معروفون من النقوش والوثائق، لكن القرى والعائلات لا تُقرأ من أسماء النخبة وحدها.",geopolitics:"صاغت الممالك المسيحية سياسة حدود وتجارة ودبلوماسية مستقلة بين مصر والسودان وطرق الصحراء.",evidence:["جداريات فرس","وثائق قصر إبريم","كنائس دنقلا القديمة","مدينة سوبا"],landmarks:["فرس","قصر إبريم","دنقلا القديمة","سوبا"],sources:[{label:"British Museum / Africa",url:"https://www.britishmuseum.org/collection/galleries/africa"},{label:"UNESCO / Dongola",url:"https://whc.unesco.org/en/tentativelists/1948/"}]},
  {id:"islamic",era:"islamic",year:"القرن 7–19 م",title:"الإسلامية النوبية: تركيب لا استبدال",region:"وادي النيل من أسوان إلى الخرطوم",tone:"copper",summary:"انتشر الإسلام في النوبة على مراحل، وتداخل مع اللغات والعادات والسلطات المحلية والتجارة عبر النهر.",monograph:["بعد البقط استمرت الممالك المسيحية قروناً، بينما نشأت مجتمعات وتجارة وروابط إسلامية حولها. كان التحول الديني بطيئاً ومتفاوتاً، وارتبط بالحركة والزيجات والسلطة والتعليم والطرق الصوفية لاحقاً.","احتفظت لغات نوبية وعادات محلية بمكانها داخل مجتمعات مسلمة، كما أعادت العربية تشكيل الإدارة والتجارة والهوية في مناطق مختلفة. لا يصح استخدام ثنائية عربي/نوبي كأنها ثابتة؛ الواقع مليء بالهويات المركبة.","من سلطنة الفونج في القرن السادس عشر إلى الإدارة التركية المصرية في القرن التاسع عشر، تغيرت شبكات السلطة والعمل والهجرة. يقرأ هذا القسم العمارة والوثائق وسير العلماء إلى جانب الذاكرة العائلية، مع فصل ما هو موثق عما يحتاج إلى رواية أهل المكان."].join(" "),milestones:[{period:"651–1500 م",title:"تجاور المسيحية والإسلام",detail:"تتوسع الروابط الإسلامية والتجارية بينما تستمر الممالك المسيحية، ولا توجد لحظة محو واحدة."},{period:"1504–1821 م / 910–1236 هـ",title:"الفونج والسلطنات",detail:"تتغير مراكز السلطة حول النيل الأزرق والوسط، وتدخل الطرق الصوفية والتجارة في إعادة تشكيل المجال."},{period:"1821 م / 1236 هـ",title:"الحكم التركي المصري",detail:"تصل جيوش محمد علي إلى السودان، وتبدأ إدارة مركزية جديدة للضرائب والتجنيد والطرق."}],lineage:"تحتاج أسماء الأسر والطرق الصوفية إلى سجلات محلية، ولا تُستنتج من الانتماء الديني وحده.",geopolitics:"أعاد الإسلام والعربية تشكيل الإدارة والحركة، مع بقاء هويات نوبية ولغات محلية حية ومركبة.",evidence:["وثائق البقط","مساجد وطرق صوفية","سجلات الضرائب والتجارة","لغات نوبية حية"],landmarks:["الطرق التجارية","الطرق الصوفية","الفونج","القرى النيلية"],sources:[{label:"Encyclopaedia Britannica / Nubia",url:"https://www.britannica.com/place/Nubia"}]},
  {id:"ottoman",era:"islamic",year:"1517–1899 م / 923–1317 هـ",title:"العثمانيون والكشّافون على النيل",region:"النوبة المصرية والسودانية",tone:"bronze",summary:"دخلت النوبة في شبكات حكم عثمانية وتركية ومصرية متبدلة، وكان الكاشف موظفاً للجباية والأمن والوساطة لا اسماً لحقبة واحدة مستقرة.",monograph:["بعد ضم مصر إلى الدولة العثمانية سنة 1517 م، بقي جنوب مصر والنوبة مجالاً حدودياً تتداخل فيه سلطة الولاة والعساكر والبيوت المحلية والتجارة. استعملت الإدارة ألقاباً ووظائف مثل الكاشف/الكاشف باشا في إدارة الأقاليم وجباية الضرائب وتأمين الطريق، لكن درجات السيطرة اختلفت من مركز إلى آخر ومن قرن إلى آخر.","في القرن التاسع عشر، ومع صعود محمد علي وأسرته منذ 1805 م ثم غزو السودان سنة 1821 م، زادت مركزية الإدارة والضرائب والتجنيد. لا ينبغي إسقاط جهاز حكومي واحد على كل قرية؛ فالسلطة اليومية مرت عبر شيوخ وبيوت وسماسرة وموانئ النهر.","تضع هذه المرحلة النوبة داخل تاريخ إمبراطوريات واتصالات واسعة، لكنها لا تلغي استقلال الذاكرة المحلية. السجل الإداري غالباً يكتب الضرائب والحدود، بينما تحفظ العائلات أسماء البيوت والهجرة والعمل."].join(" "),milestones:[{period:"1517 م / 923 هـ",title:"ضم مصر إلى العثمانيين",detail:"تدخل مصر في النظام العثماني، وتبقى النوبة الجنوبية منطقة تماس وإدارة متدرجة."},{period:"القرنان السادس عشر–الثامن عشر",title:"الكشّاف والجباية",detail:"تعمل وظائف إقليمية للجباية والأمن والوساطة، مع اختلاف تاريخي ومحلي في مدى السلطة."},{period:"1805 م / 1220 هـ",title:"صعود محمد علي",detail:"تتوسع إدارة الأسرة العلوية في مصر وتعيد تنظيم الضرائب والجيش والطرق."},{period:"1821 م / 1236 هـ",title:"التوسع جنوباً",detail:"تدخل الجيوش التركية المصرية السودان وتعيد رسم الإدارة والاقتصاد على النيل."}],lineage:"لا يساوي لقب الكاشف نسباً قبلياً؛ أسماء الوظائف والبيوت يجب أن تُقرأ من سجلات محلية لا من اللقب وحده.",geopolitics:"جعلت الحدود والضرائب والتجنيد النوبة ممراً استراتيجياً بين مصر والسودان، مع بقاء المجتمع وسيطاً لا متلقياً سلبياً.",evidence:["سجلات الإدارة العثمانية","دفاتر الضرائب","طرق التجارة النيلية","روايات البيوت المحلية"],landmarks:["موانئ النيل","طرق القوافل","مراكز الجباية","القرى الحدودية"],sources:[{label:"Encyclopaedia Britannica / Nubia",url:"https://www.britannica.com/place/Nubia"}]},
  {id:"modern",era:"modern",year:"1899–اليوم / 1317–1448 هـ",title:"الحدود والسدود والتهجير",region:"النوبة المصرية والسودانية والشتات",tone:"crimson",summary:"رسمت اتفاقات الحدود ومشروعات المياه والعمل والهجرة جغرافيا جديدة، بينما أعادت المجتمعات بناء الذاكرة في أماكن جديدة.",monograph:["في 1899 م / 1317 هـ نشأ الحكم الثنائي الأنجلو-مصري في السودان، ورُسمت الحدود الإدارية الحديثة فوق مجال نَهَري سابق. ظهرت توترات حول وادي حلفا ومثلث حلايب ومواقع العبور، وتغيرت إدارة الأرض والعمل والتعليم مع الإدارة الاستعمارية.","أقيم خزان أسوان سنة 1902 م، ثم رُفع منسوبه في 1912 و1933، قبل بناء السد العالي منذ 1960 م وبدء ملء بحيرة ناصر في 1964 م. في النوبة المصرية نُقلت قرى كثيرة إلى مناطق حول كوم أمبو، وفي وادي حلفا السوداني نُقلت مجتمعات إلى منطقة خشم القربة/حلفا الجديدة. الأرقام والتوزيعات تختلف بحسب القرية والمصدر، لذلك لا تُختزل التجربة في رقم واحد.","التهجير ليس خاتمة. هو فقد للمقابر والحقول ومسارات الماء، وإعادة بناء للبيت والعمل واللغة والقرابة. تكمل الجمعيات والأغاني والزيارات والأرشيفات العائلية ما لم تحفظه الخرائط الرسمية."].join(" "),milestones:[{period:"1899 م / 1317 هـ",title:"الحكم الثنائي والحدود الحديثة",detail:"تدخل السودان في الحكم الأنجلو-مصري، وتترسخ حدود إدارية جديدة على مجال نوبي متصل."},{period:"1902 م / 1320 هـ",title:"خزان أسوان الأول",detail:"يرتفع ضغط الماء على النوبة السفلى وتبدأ سلسلة تغييرات في القرى والمواقع الأثرية."},{period:"1912 و1933 م",title:"رفع منسوب الخزان",detail:"تتكرر موجات التأثر والغمر الجزئي، وتزداد أعمال التوثيق والإنقاذ."},{period:"1960–1964 م / 1379–1384 هـ",title:"السد العالي والتهجير",detail:"يبدأ بناء السد العالي، ويغمر ارتفاع بحيرة ناصر قرى ومواقع في النوبة المصرية؛ تستمر إعادة التوطين في الستينيات."},{period:"1971 م / 1391 هـ",title:"اكتمال السد العالي",detail:"تستقر البحيرة الجديدة كجغرافيا سياسية ومائية، بينما تبقى أسئلة العودة والحق في الأرض والذاكرة مفتوحة."}],lineage:"لا تملأ سجلات الدولة غياب شجرة الأسرة؛ تُحفظ الأنساب في دفاتر العائلات والشهادات والزيارات، وتحتاج موافقة أصحابها قبل النشر.",geopolitics:"حوّل السد والحدود النوبة من مجال نهري متصل إلى شبكة قرى وشتات ومدن عمل، وأصبح حفظ الذاكرة فعلاً سياسياً وثقافياً.",evidence:["خرائط الإنقاذ","سجلات إعادة التوطين","صور القرى قبل الغمر","أرشيفات الأسر والنوادي النوبية"],landmarks:["بحيرة ناصر","قرى كوم أمبو","وادي حلفا","أرشيفات الشتات"],sources:[{label:"UNESCO / Nubian Monuments",url:"https://whc.unesco.org/en/list/88/"},{label:"Nubian Museum / Egypt",url:"https://egymonuments.gov.eg/en/museums/nubian-museum"}]}
];
