  Kerma:{meaning:"كرمة: اسم العاصمة الأثرية لمملكة كوش المبكرة",coordinates:"19.60°N, 30.41°E · موقع كرمة الحالي",families:["القبور والدفوفة لا تمنح أسماء أسر حديثة؛ سجل المجتمع المحلي مستقل"],displacement:"الموقع الأثري ليس قرية مهجرة واحدة؛ تُقرأ حماية الأثر بجوار حياة المجتمعات النيلية.",resettlement:"قرى دنقلا والشمال السوداني بحسب مشاريع الماء والعمل",events:["نحو 2500–1500 ق.م: المملكة","الدفوفة والجبانات","الزراعة والتجارة عبر الشلال"]},
  Nuri:{meaning:"نوري: جبانة ملكية كوشية على الضفة",coordinates:"18.55°N, 31.82°E · نطاق جبانة نوري التقريبي",families:["الأهرام تثبت دفناً ملكياً ولا تثبت قبائل قرى اليوم"],displacement:"موقع الجبانة جزء من مشهد نهر متغير؛ لا يساوي السجل الأثري تاريخ قرية معاصرة.",resettlement:"القرى المحيطة بدنقلا والشتات السوداني",events:["جبانة ملوك وملكات كوش","استمرار قداسة نبتة","التنقيب والحفظ"]},
  Meroe:{meaning:"مروي: عاصمة كوش المتأخرة ومركز الكتابة والورش",coordinates:"16.94°N, 33.75°E · موقع البجراوية/مروي",families:["اللقب المروي لا يمنح نسباً حديثاً؛ العائلات المعاصرة تحتاج مصادرها الخاصة"],displacement:"الموقع الأثري ليس قرية سدّية، وتُفصل حماية البجراوية عن تاريخ تهجير قرى النيل.",resettlement:"القرى والمدن السودانية الحديثة حول النيل والبطانة",events:["نحو 300 ق.م: انتقال المركز","الخط المروي والورش","نحو 350 م: تراجع النظام المروي"]}
