if(andanRecord)Object.assign(andanRecord,{families:["Gaber family / عائلة جابر عبد الوهاب: Abdel-Wahab Gaber Abdel-Wahab, Mohamed Gaber Abdel-Wahab, Fatma Gaber Abdel-Wahab, and Nawal Gaber Abdel-Wahab — names supplied for this project archive; no additional lineage is asserted.","Dahab family / عائلة دهب: Fathy Hassan Dahab appears as a separate memorial record; no relation to the Gaber family is inferred.","Other Andan families, lineages, and clans: no verified names were supplied in the current archive. Add them with family consent and a source rather than inventing a complete list."],genealogy:[{label:"عبد الوهاب جابر عبد الوهاب",detail:"Foundational memorial record in the supplied family archive."},{label:"محمد جابر عبد الوهاب",detail:"Named living branch in the supplied archive; additional relationship details require family documentation."},{label:"فاطمة جابر عبد الوهاب / Fatma Gaber Abdel-Wahab",detail:"Added to the Gaber family tree at the project owner's request; no further personal details are inferred."},{label:"نوال جابر عبد الوهاب / Nawal Gaber Abdel-Wahab",detail:"Added to the Gaber family tree at the project owner's request; no further personal details are inferred."}],familyArchiveStatus:"The directory is open for documented additions, but private clan names are not fabricated or published without the family's permission."});
